package com.prakash.gmcemp.emission.controller;import com.prakash.gmcemp.emission.dto.*;import com.prakash.gmcemp.emission.model.*;import com.prakash.gmcemp.emission.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/emissions") public class EmissionController{private final EmissionService service;public EmissionController(EmissionService s){service=s;}@PostMapping("/calculate")ResponseEntity<EmissionCalculation> calculate(@Valid @RequestBody CalculationRequest r){return ResponseEntity.status(201).body(service.calculate(r));}@GetMapping("/shipment/{id}")List<EmissionCalculation> byShipment(@PathVariable Long id){return service.byShipment(id);}@GetMapping List<EmissionCalculation> all(){return service.all();}}